#!/usr/bin/env bash
# Completes the bundle generated by quarkus-operator-sdk-bundle-generator with what the generator cannot express:
#   - spec.relatedImages in the CSV (read from olm/related-images.txt)
#   - the supported OpenShift versions (annotation and bundle label)
#   - the scorecard configuration (tests/scorecard, annotations and bundle labels)
# Everything else (createdAt, containerImage, replaces, olm.skipRange) is set through application.properties
# and the -D flags that olm/Makefile passes to Maven.
#
# Usage: finish-bundle.sh <bundle-dir>
# Environment:
#   OPENSHIFT_VERSIONS  value of com.redhat.openshift.versions (default: v4.12)
#   OPERAND_TAG         replaces ':latest' in the quay.io/wanaku images of related-images.txt (default: keep)

set -euo pipefail

OLM_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
BUNDLE_DIR="${1:?Usage: $0 <bundle-dir>}"
OPENSHIFT_VERSIONS="${OPENSHIFT_VERSIONS:-v4.12}"
OPERAND_TAG="${OPERAND_TAG:-}"

CSV=("${BUNDLE_DIR}"/manifests/*.clusterserviceversion.yaml)
[[ ${#CSV[@]} -eq 1 && -f "${CSV[0]}" ]] || { echo "Expected exactly one CSV in ${BUNDLE_DIR}/manifests" >&2; exit 1; }

# spec is the last top-level key of the generated CSV, so appending relatedImages keeps the document valid.
# The first 'image:' of the CSV is the operator Deployment image.
OPERATOR_IMAGE="$(awk '/^ +image: / { print $2; exit }' "${CSV[0]}")"
[[ -n "${OPERATOR_IMAGE}" ]] || { echo "Could not find the operator image in the CSV" >&2; exit 1; }

{
  echo "  relatedImages:"
  echo "  - name: wanaku-operator"
  echo "    image: ${OPERATOR_IMAGE}"
  while read -r name image; do
    [[ -z "${name}" || "${name}" == \#* ]] && continue
    if [[ -n "${OPERAND_TAG}" && "${image}" == quay.io/wanaku/*:latest ]]; then
      image="${image%latest}${OPERAND_TAG}"
    fi
    echo "  - name: ${name}"
    echo "    image: ${image}"
  done < "${OLM_DIR}/related-images.txt"
} >> "${CSV[0]}"

cat >> "${BUNDLE_DIR}/metadata/annotations.yaml" <<EOF
  com.redhat.openshift.versions: "${OPENSHIFT_VERSIONS}"
  operators.operatorframework.io.test.mediatype.v1: scorecard+v1
  operators.operatorframework.io.test.config.v1: tests/scorecard/
EOF

DOCKERFILE="${BUNDLE_DIR}/bundle.Dockerfile"
awk -v versions="${OPENSHIFT_VERSIONS}" '
  /^# Copy files to locations specified by labels\./ {
    print "LABEL operators.operatorframework.io.test.mediatype.v1=scorecard+v1"
    print "LABEL operators.operatorframework.io.test.config.v1=tests/scorecard/"
    print "LABEL com.redhat.openshift.versions=" versions
    print ""
  }
  { print }
' "${DOCKERFILE}" > "${DOCKERFILE}.tmp"
mv "${DOCKERFILE}.tmp" "${DOCKERFILE}"
echo "COPY tests/scorecard /tests/scorecard/" >> "${DOCKERFILE}"

mkdir -p "${BUNDLE_DIR}/tests/scorecard"
cp "${OLM_DIR}/scorecard/config.yaml" "${BUNDLE_DIR}/tests/scorecard/config.yaml"
echo "Finished the bundle in ${BUNDLE_DIR}"
